cat > main.ts <<'EOF'
// Keyed totals: sum signed 64-bit values per key, answer queries in order.
const MIN = -(1n << 63n);
const MAX = (1n << 63n) - 1n;

// Keys are compared by bytes, so decode as latin1 (one char per byte) and
// re-encode the same way on output.
function latin1(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i += 8192) {
    s += String.fromCharCode(...bytes.subarray(i, i + 8192));
  }
  return s;
}

function toBytes(s: string): Uint8Array {
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

const path = Deno.args[0];
const text = latin1(Deno.readFileSync(path));
const lines = text.split("\n");
if (lines.length && lines[lines.length - 1] === "") lines.pop();
for (let i = 0; i < lines.length; i++) {
  if (lines[i].endsWith("\r")) lines[i] = lines[i].slice(0, -1);
}

const OVERFLOW = Symbol("overflow");
const totals = new Map<string, bigint | typeof OVERFLOW>();

let i = 0;
for (; i < lines.length && lines[i] !== ""; i++) {
  const line = lines[i];
  const sp = line.indexOf(" ");
  if (sp < 0) continue;
  const key = line.slice(0, sp);
  let v: bigint;
  try {
    v = BigInt(line.slice(sp + 1).trim());
  } catch {
    continue;
  }
  const cur = totals.get(key);
  if (cur === OVERFLOW) continue;
  const next = (cur ?? 0n) + v;
  totals.set(key, next < MIN || next > MAX ? OVERFLOW : next);
}

const chunks: string[] = [];
for (i++; i < lines.length; i++) {
  const key = lines[i];
  const t = totals.get(key);
  chunks.push(
    key + "=" + (t === undefined ? "absent" : t === OVERFLOW ? "overflow" : t.toString()) + "\n",
  );
}
const out = toBytes(chunks.join(""));
let off = 0;
while (off < out.length) off += Deno.stdout.writeSync(out.subarray(off));
EOF
